// Member-facing Notification Center (Community & Commerce track, item
// 11), mounted at /notifications. Every signed-in portal account has
// its own notification history here, generated by utils/notifications.js's
// notify() - never hand-entered. /notifications/preferences is a
// member's own per-type email/sms opt-out (in-app can't be turned off -
// see the migration's own comment on notification_preferences).
const express = require('express');
const router = express.Router();
const { requirePortalAuth } = require('../middleware/portalAuth');
const notifications = require('../utils/notifications');
const { paginate, parsePage, parsePageSize, DEFAULT_PAGE_SIZE } = require('../utils/pagination');

router.use(requirePortalAuth);

router.get('/', async (req, res) => {
  const allItems = await notifications.listForAccount(req.portalAccount.id);
  // Same pagination (utils/pagination.js) the Members/Logs/Library admin
  // lists already use - a long-lived account's full notification history
  // is the same "renders as one enormous DOM list" problem those lists
  // were paginated to fix. hasUnread is checked against the FULL list,
  // not just this page's slice - Mark All Read has to stay visible
  // whenever any page has unread items, not only the one currently open.
  const pageSize = parsePageSize(req.query.pageSize, DEFAULT_PAGE_SIZE);
  const pagination = paginate(allItems, parsePage(req.query.page), pageSize);
  res.render('notifications-list', {
    title: 'Notifications',
    items: pagination.items,
    hasUnread: allItems.some((i) => !i.read_at),
    pagination,
    viewingAll: pageSize === Infinity,
    baseHref: '/notifications?',
  });
});

router.post('/:id/read', async (req, res) => {
  await notifications.markRead(req.portalAccount.id, req.params.id);
  res.redirect(req.get('Referer') || '/notifications');
});

router.post('/read-all', async (req, res) => {
  await notifications.markAllRead(req.portalAccount.id);
  res.redirect('/notifications');
});

router.get('/preferences', async (req, res) => {
  const preferences = await notifications.preferencesForAccount(req.portalAccount.id);
  res.render('notifications-preferences', { title: 'Notification Preferences', preferences, notice: req.query.notice || null });
});

router.post('/preferences', async (req, res) => {
  const types = await notifications.listTypes();
  for (const type of types) {
    await notifications.setPreference(req.portalAccount.id, type.key, 'email', req.body[`email_${type.key}`] === '1');
    // A type that's always email-only (sms_enabled off) has no SMS
    // checkbox on the form at all - skip writing a preference row for
    // it rather than saving a meaningless "opted out" from a field that
    // was never shown.
    if (type.sms_enabled) await notifications.setPreference(req.portalAccount.id, type.key, 'sms', req.body[`sms_${type.key}`] === '1');
    await notifications.setPreference(req.portalAccount.id, type.key, 'push', req.body[`push_${type.key}`] === '1');
  }
  res.redirect('/notifications/preferences?notice=' + encodeURIComponent('Saved.'));
});

module.exports = router;
